params.source:
def request = (Map) input
def documents = (List) request.documents
def collection = request.collectionId?.toString()
def includeText = request.includeText?.toString() != 'false'
if(documents == null || !collection) throw new IllegalArgumentException('documents and collectionId are required')
def config = new Properties()
new File(System.getProperty('user.home'),'.local/share/trikeshed/npo-demo/postgres.properties').withInputStream { config.load(it) }
def db = new org.postgresql.ds.PGSimpleDataSource()
db.setServerNames([config.getProperty('server')] as String[])
db.setPortNumbers([Integer.parseInt(config.getProperty('port'))] as int[])
db.setDatabaseName(config.getProperty('database'))
db.setUser(config.getProperty('user'))
db.setPassword(config.getProperty('password'))
db.setConnectTimeout(5)
getContext().getRegistry().bind('npo',db)
def schema = "CREATE TABLE IF NOT EXISTS npo_source (collection_id text NOT NULL, source_id text NOT NULL, original_cid text NOT NULL, extracted_text_cid text NOT NULL, source_url text NOT NULL, content text NOT NULL, route text NOT NULL CHECK(route IN ('ready','review')), seen_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(collection_id,original_cid,extracted_text_cid))"
def insert = "INSERT INTO npo_source(collection_id,source_id,original_cid,extracted_text_cid,source_url,content,route) VALUES(:?collectionId,:?sourceId,:?originalCid,:?extractedTextCid,:?sourceUrl,:?contentText,:?route) ON CONFLICT(collection_id,original_cid,extracted_text_cid) DO UPDATE SET source_id=EXCLUDED.source_id,source_url=EXCLUDED.source_url,content=EXCLUDED.content,route=EXCLUDED.route,seen_at=now()"
def select = "SELECT jsonb_build_object('collectionId',CAST(:?collectionId AS text),'storedCount',count(*),'readyCount',count(*) FILTER (WHERE route='ready'),'reviewCount',count(*) FILTER (WHERE route='review'),'documents',COALESCE(jsonb_agg(jsonb_build_object('sourceId',source_id,'originalCid',original_cid,'extractedTextCid',extracted_text_cid,'sourceUrl',source_url,'text',content,'route',route) ORDER BY original_cid,extracted_text_cid),'[]'::jsonb))::text AS payload FROM npo_source WHERE collection_id=:?collectionId"
from('direct:npo-extract').routeId('npo-source-enrichment')
 .process { e ->
   def r = new LinkedHashMap((Map)e.message.body)
   if(!r.containsKey('text')) {
     if(!r.project || !r.sourceId) throw new IllegalArgumentException('project and sourceId required for extraction')
     if(!(r.originalCid instanceof String) || !(r.originalCid ==~ /sha256:[0-9a-f]{64}/))
       throw new IllegalArgumentException('Canonical original document CID required for project extraction')
     def invoke = { String type, Map params ->
       def connection = (java.net.HttpURLConnection)new URL('http://127.0.0.1:8890/api/lcnc/run').openConnection()
       connection.requestMethod='POST'; connection.doOutput=true; connection.connectTimeout=5000; connection.readTimeout=60000
       connection.setRequestProperty('Content-Type','application/json')
       try {
         def data=groovy.json.JsonOutput.toJson([type:type,params:params])
         connection.outputStream.withCloseable { it.write(data.getBytes('UTF-8')) }
         if(connection.responseCode!=200) throw new IllegalStateException('Project node failed: '+type+' HTTP '+connection.responseCode)
         def result=connection.inputStream.withCloseable { new groovy.json.JsonSlurper().parse(it,'UTF-8') }
         if(result.ok!=true) throw new IllegalStateException('Project node refused: '+type)
         return (Map)result.outputs
       } finally { connection.disconnect() }
     }
     def identity = { ->
       def inventory=invoke('project.docs',[project:r.project,prefix:r.sourceId,limit:'1'])
       def current=((List)inventory.docs).find { d -> d.id==r.sourceId }
       return current
     }
     def before=identity()
     if(before?.cid!=r.originalCid) throw new IllegalArgumentException('Original document CID does not match project inventory')
     def result=invoke('project.extract',[project:r.project,id:r.sourceId])
     def after=identity()
     if(after?.cid!=r.originalCid) throw new IllegalStateException('Original document identity changed during extraction')
     if(result.found==true) {
       def twin=invoke('project.read',[project:r.project,id:r.sourceId+'.extract.md',maxChars:'1']).doc
       if(twin?.cid!=result.cid) throw new IllegalStateException('Extraction identity changed during read')
       def origin=invoke('project.read',[project:r.project,id:r.sourceId+'.extract-origin.tsv',maxChars:'512'])
       def pair=origin.text instanceof String ? origin.text.split('\t',-1) : new String[0]
       if(pair.length!=2 || pair[0]!=r.originalCid || pair[1]!=result.cid)
         throw new IllegalStateException('Extraction origin does not match source and text identities')
     }
     r.text=result.text ?: ''; r.extractedTextCid=result.cid ?: ''; r.extractionFound=result.found
   }
   e.message.body=r
 }
from(entry).routeId('npo-postgres-eip')
 .setBody(constant(schema)).to('jdbc:npo')
 .setBody(constant(documents))
 .split(body()).stopOnException()
   .enrich('direct:npo-extract', { original, enriched -> enriched } as org.apache.camel.AggregationStrategy)
   .process { e ->
     def r=(Map)e.message.body
     if(!r.sourceId || !r.originalCid) throw new IllegalArgumentException('source identity required')
     def text=r.text instanceof String?r.text:''
     if(!text.isEmpty() || r.extractedTextCid) {
       if(!(r.extractedTextCid instanceof String) || !(r.extractedTextCid ==~ /sha256:[0-9a-f]{64}/))
         throw new IllegalArgumentException('Canonical extracted text CID required for retained content')
       def digest=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance('SHA-256').digest(text.getBytes(java.nio.charset.StandardCharsets.UTF_8)))
       if(r.extractedTextCid != ('sha256:'+digest))
         throw new IllegalArgumentException('Extracted text digest does not match retained content')
     }
     e.message.setHeader('collectionId',collection)
     e.message.setHeader('sourceId',r.sourceId.toString())
     e.message.setHeader('originalCid',r.originalCid.toString())
     e.message.setHeader('extractedTextCid',r.extractedTextCid?.toString()?:'')
     e.message.setHeader('sourceUrl',r.sourceUrl?.toString()?:'')
     e.message.setHeader('contentText',text)
     e.message.setHeader('textAvailable',!text.isBlank() && r.extractionFound!=false)
   }
   .choice()
     .when(header('textAvailable').isEqualTo(true)).setHeader('route',constant('ready'))
     .otherwise().setHeader('route',constant('review'))
   .end()
   .setBody(constant(insert)).to('jdbc:npo?useHeadersAsParameters=true')
 .end()
 .setHeader('collectionId',constant(collection))
 .setBody(constant(select)).to('jdbc:npo?useHeadersAsParameters=true')
 .removeHeaders('*')
 .process { e ->
   def rows=(List)e.message.body
   if(rows.size()!=1) throw new IllegalStateException('Expected PostgreSQL readback envelope')
   def packet=new groovy.json.JsonSlurper().parseText(rows[0].payload.toString())
   packet.documents.each { r ->
     String text=r.text
     r.textChars=text.length()
     def passages=[];int matches=0
     def lines=java.util.regex.Pattern.compile('[^\\r\\n]+').matcher(text)
     def terms=java.util.regex.Pattern.compile('(?i)\\b(impact|outcomes?|outputs?|activities|activity|indicators?|assumptions?)\\b')
     while(lines.find()) {
       if(terms.matcher(lines.group()).find()) {
         matches++
         if(passages.size()<8) passages.add([text:lines.group(),begin:lines.start(),end:lines.end()])
       }
     }
     r.passages=passages;r.passageCount=matches;r.passagesTruncated=matches>8
     if(!includeText) r.remove('text')
   }
   e.message.body=groovy.json.JsonOutput.toJson(packet)
 }
